function zoomRunSettings(settings, now) {
  if (
    !settings ||
    !/^[A-Za-z0-9_-]{4,100}$/.test(settings.accountId) ||
    !/^[A-Za-z0-9_-]{4,100}$/.test(settings.hostId) ||
    typeof settings.ownerName !== "string" ||
    !settings.ownerName.trim() ||
    settings.ownerName.length > 120 ||
    typeof settings.model !== "string" ||
    !settings.model.trim()
  ) {
    throw Error("Configure the Zoom account ID, host user ID, owner name and OpenAI model.");
  }
  if (!Array.isArray(settings.routes) || !settings.routes.length)
    throw Error("Configure at least one authorized meeting route.");
  const titles = new Set();
  for (const route of settings.routes) {
    if (
      typeof route.title !== "string" ||
      !route.title.trim() ||
      route.title.length > 180 ||
      /[\r\n]/.test(route.title) ||
      titles.has(route.title) ||
      !/^[^\s,@<>]+@[^\s,@<>]+\.[^\s,@<>]+$/.test(route.recipient) ||
      !/^[1-9]\d{0,29}$/.test(route.listId) ||
      typeof route.calendarId !== "string" ||
      !/^[A-Za-z0-9_+=-]{1,500}$/.test(route.calendarId)
    )
      throw Error("Invalid or duplicate meeting route.");
    titles.add(route.title);
  }
  return {
    ...settings,
    now,
    from: new Date(now - 86_400_000).toISOString().slice(0, 10),
    to: new Date(now).toISOString().slice(0, 10),
  };
}

const setup = zoomRunSettings(
  {
    accountId: "",
    hostId: "",
    ownerName: "",
    model: "gpt-4o",
    routes: [],
  },
  Date.now(),
);
return [{ json: setup }];

function zoomToken(body) {
  if (
    typeof body?.access_token !== "string" ||
    !/^[A-Za-z0-9_.~-]+$/.test(body.access_token) ||
    body.token_type?.toLowerCase() !== "bearer"
  )
    throw Error("Zoom OAuth did not return a valid access token.");
  return body.access_token;
}

return [{ json: { token: zoomToken($input.first().json.body) } }];

function zoomPageToken(page) {
  const token = page?.next_page_token;
  if (typeof token !== "string" || token.length > 4096)
    throw Error("Zoom did not confirm the next-page token.");
  return token;
}

function zoomDownloadUrl(value, previous) {
  if (typeof value !== "string" || value.length > 4096)
    throw Error("Zoom returned an invalid recording address.");
  const zoomOrigin = /^https:\/\/((?:[a-z0-9](?:[a-z0-9-]*[a-z0-9])?\.)*zoom\.us)(?=\/)/i;
  const origin = zoomOrigin.exec(value);
  const base = origin
    ? origin[0]
    : previous && value.startsWith("/")
      ? zoomOrigin.exec(previous)?.[0]
      : null;
  const path = origin ? value.slice(origin[0].length) : value;
  if (
    !base ||
    !/^\/{1,2}(?:rec\/(?:archive\/|meeting\/transcript\/)?download|recording\/download)\/[A-Za-z0-9_.~%+/=-]+(?:\?[A-Za-z0-9_.~%/+&=:-]+)?$/.test(
      path,
    ) ||
    /(?:^|\/)(?:\.|%2e){1,2}(?=\/|\?|$)/i.test(path) ||
    /%(?:2f|5c)/i.test(path.split("?")[0])
  ) {
    throw Error("Zoom returned an unapproved recording download address.");
  }
  return base + path;
}

function zoomRecordingPlans(pages, settings) {
  const results = new Map();
  if (!pages.length || zoomPageToken(pages.at(-1)))
    throw Error("The recording list is incomplete.");
  for (const page of pages) {
    if (!Array.isArray(page.meetings)) throw Error("Zoom returned an invalid recording list.");
    for (const record of page.meetings) {
      const route = settings.routes.find((candidate) => candidate.title === record?.topic);
      const began = Date.parse(record?.start_time);
      if (
        !route ||
        record.account_id !== settings.accountId ||
        record.host_id !== settings.hostId ||
        !["2", "8"].includes(String(record.type)) ||
        !Number.isFinite(began) ||
        began < settings.now - 86_400_000 ||
        began > settings.now
      )
        continue;
      if (typeof record.uuid !== "string" || !/^[A-Za-z0-9+/=_-]{1,160}$/.test(record.uuid)) {
        throw Error("Zoom did not identify the recorded meeting occurrence.");
      }
      const transcript = record.recording_files?.find(
        (file) =>
          file.file_type === "TRANSCRIPT" &&
          (!file.status || file.status === "completed") &&
          typeof file.download_url === "string",
      );
      if (!transcript) continue;
      if (Number(transcript.file_size) > 1_000_000)
        throw Error("A Zoom transcript exceeds the 1 MB processing limit.");
      const encoded = encodeURIComponent(record.uuid);
      const key = "zoom:" + settings.hostId + ":" + record.uuid;
      const candidate = {
        id: record.uuid,
        key,
        title: record.topic,
        began: new Date(began).toISOString(),
        route,
        downloadUrl: zoomDownloadUrl(transcript.download_url),
        uuidPath: record.uuid.includes("/") ? encodeURIComponent(encoded) : encoded,
        ownerName: settings.ownerName,
        model: settings.model,
      };
      if (results.has(key) && JSON.stringify(results.get(key)) !== JSON.stringify(candidate)) {
        throw Error("Zoom returned inconsistent references for the same meeting occurrence.");
      }
      results.set(key, candidate);
    }
  }
  if (results.size > 20) throw Error("There are more than 20 approved recordings in this run.");
  return [...results.values()];
}

return zoomRecordingPlans(
  $input.all().map((item) => item.json.body),
  $("Configure Zoom host and authorized meeting routes").last(0).json,
).map((json) => ({ json }));

return [
  { json: { id: $("Process one meeting occurrence").last(1).json.id, status: "already_reserved" } },
];

function zoomDownloadUrl(value, previous) {
  if (typeof value !== "string" || value.length > 4096)
    throw Error("Zoom returned an invalid recording address.");
  const zoomOrigin = /^https:\/\/((?:[a-z0-9](?:[a-z0-9-]*[a-z0-9])?\.)*zoom\.us)(?=\/)/i;
  const origin = zoomOrigin.exec(value);
  const base = origin
    ? origin[0]
    : previous && value.startsWith("/")
      ? zoomOrigin.exec(previous)?.[0]
      : null;
  const path = origin ? value.slice(origin[0].length) : value;
  if (
    !base ||
    !/^\/{1,2}(?:rec\/(?:archive\/|meeting\/transcript\/)?download|recording\/download)\/[A-Za-z0-9_.~%+/=-]+(?:\?[A-Za-z0-9_.~%/+&=:-]+)?$/.test(
      path,
    ) ||
